QString str(NSString* s){return s?QString::fromUtf8([s UTF8String]):QString();}
class MacMonitor final:public MonitorProvider {
    quint64 total_=0,idle_=0;
public:Frame read(const QVariantMap& settings)override{@autoreleasepool{Frame f;auto& s=f.sample;s.at=QDateTime::currentDateTimeUtc();natural_t cpus=0;processor_info_array_t info=nullptr;mach_msg_type_number_t count=0;if(host_processor_info(mach_host_self(),PROCESSOR_CPU_LOAD_INFO,&cpus,&info,&count)==KERN_SUCCESS){auto stats=reinterpret_cast<processor_cpu_load_info_t>(info);quint64 total=0,idle=0;for(natural_t i=0;i<cpus;i++)for(int j=0;j<CPU_STATE_MAX;j++){total+=stats[i].cpu_ticks[j];if(j==CPU_STATE_IDLE)idle+=stats[i].cpu_ticks[j];}if(total_&&total>total_)s.cpu=Reading::of(std::clamp(100.*(1.-double(idle-idle_)/(total-total_)),0.,100.),"%","Mach CPU-time utilization");else s.cpu=Reading::missing("%","CPU counter warming up",Availability::WarmingUp);total_=total;idle_=idle;vm_deallocate(mach_task_self(),reinterpret_cast<vm_address_t>(info),count*sizeof(integer_t));}
    char name[256]{};size_t length=sizeof name;if(sysctlbyname("machdep.cpu.brand_string",name,&length,nullptr,0)!=0){length=sizeof name;sysctlbyname("hw.model",name,&length,nullptr,0);}s.cpuName=QString::fromUtf8(name);quint64 physical=0;length=sizeof physical;sysctlbyname("hw.memsize",&physical,&length,nullptr,0);vm_statistics64_data_t vm{};mach_msg_type_number_t vmCount=HOST_VM_INFO64_COUNT;vm_size_t page=0;host_page_size(mach_host_self(),&page);if(physical&&host_statistics64(mach_host_self(),HOST_VM_INFO64,reinterpret_cast<host_info64_t>(&vm),&vmCount)==KERN_SUCCESS){quint64 available=(quint64(vm.free_count)+vm.inactive_count)*page;s.ramTotal=Reading::of(double(physical),"bytes");s.ramUsed=Reading::of(double(physical-std::min(physical,available)),"bytes","Physical memory minus free and inactive pages; differs from Activity Monitor memory pressure");}
    NSArray<id<MTLDevice>>* devices=MTLCopyAllDevices();id<MTLDevice> selected=nil;for(id<MTLDevice> device in devices){QString id=QString::number(device.registryID,16);f.adapters<<Adapter{id,str(device.name),"metal:"+id,0,!device.hasUnifiedMemory};if(!selected||settings["GpuId"].toString()=="metal:"+id||settings["GpuId"].toString()==id)selected=device;}
    s.gpu=Reading::missing("%","Aggregate system GPU utilization has no validated public provider yet");s.vramUsed=Reading::missing("bytes","System-wide GPU allocation is unavailable through this provider");s.vramTotal=Reading::missing("bytes","Dedicated VRAM capacity is not exposed by this provider");if(selected){s.gpuId=QString::number(selected.registryID,16);s.gpuName=str(selected.name);if(selected.hasUnifiedMemory){s.memoryModel="unified";s.vramUsed=Reading::missing("bytes","Unified memory is shared with RAM; it is not dedicated VRAM");s.vramTotal=Reading::missing("bytes","Unified memory; no dedicated VRAM capacity");}}
    s.cpuTemperature=Reading::missing("°C","No validated public macOS temperature provider; private SMC APIs are not used");s.gpuTemperature=Reading::missing("°C","No validated public macOS temperature provider");return f;}}
};
class MacCapture final:public SurfaceCapture {
