void MacPlatform::reconcile(){if(!attached_)return;auto app=[NSRunningApplication runningApplicationWithProcessIdentifier:native_->pid];if(native_->destroyed||!app||app.terminated){detach();emit targetLost();return;}CFTypeRef minimized=nullptr;bool mini=AXUIElementCopyAttributeValue(native_->target,kAXMinimizedAttribute,&minimized)==kAXErrorSuccess&&CFGetTypeID(minimized)==CFBooleanGetTypeID()&&CFBooleanGetValue(static_cast<CFBooleanRef>(minimized));if(minimized)CFRelease(minimized);auto host=axBounds(native_->target);if(mini||app.hidden||host.isEmpty()||!userVisible_||selecting_){[native_->window orderOut:nil];emit changed();return;}if(!dragging_&&host!=native_->host){native_->host=host;auto anchor=absoluteAnchor(host,native_->relative);double d=window_->devicePixelRatio();place(fitHost(QRect(host.topLeft()*d,host.size()*d),anchor*d,logical_,scale_*d,radius_));}
