void MacPlatform::fitCurrent(){if(!attached_){Platform::fitCurrent();return;}auto host=axBounds(native_->target);double d=window_->devicePixelRatio();auto b=bounds();place(fitHost(QRect(host.topLeft()*d,host.size()*d),{b.x()+b.width(),b.y()},logical_,scale_*d,radius_));}
void MacPlatform::endDrag(){Platform::endDrag();if(attached_){auto b=bounds();double d=window_->devicePixelRatio();native_->relative=relativeAnchor(axBounds(native_->target),QPoint(qRound((b.x()+b.width())/d),qRound(b.y()/d)));}}
void MacPlatform::detach(){native_->clearTarget();Platform::detach();native_->window.level=NSFloatingWindowLevel;}
