bool MacPlatform::canHover()const{return Platform::canHover()&&(!attached_||NSWorkspace.sharedWorkspace.frontmostApplication.processIdentifier==native_->pid);}
QVector<QRect> MacPlatform::coveredAreas()const{QVector<QRect> list;NSArray* windows=CFBridgingRelease(CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly,kCGNullWindowID));for(NSDictionary* item in windows){if([item[(id)kCGWindowNumber] integerValue]==native_->window.windowNumber)break;if([item[(id)kCGWindowOwnerPID] intValue]==getpid())continue;CGRect r{};if(CGRectMakeWithDictionaryRepresentation((__bridge CFDictionaryRef)item[(id)kCGWindowBounds],&r)){double d=window_->devicePixelRatio();QRect rect(qRound(r.origin.x*d),qRound(r.origin.y*d),qRound(r.size.width*d),qRound(r.size.height*d));if(rect.intersects(bounds()))list<<rect;}}return list;}
void MacPlatform::beginSelection(){if(!AXIsProcessTrusted()||!qEnvironmentVariableIsSet("GLASSSTATS_EXPERIMENTAL_WINDOWING")){emit status("Experimental attachment requires Accessibility permission and GLASSSTATS_EXPERIMENTAL_WINDOWING=1.");return;}selecting_=true;[native_->window orderOut:nil];auto callback=[](CGEventTapProxy,CGEventType type,CGEventRef event,void* context)->CGEventRef{auto self=static_cast<MacPlatform*>(context);if(type==kCGEventTapDisabledByTimeout||type==kCGEventTapDisabledByUserInput){self->cancelSelection();return event;}if(type==kCGEventKeyDown&&CGEventGetIntegerValueField(event,kCGKeyboardEventKeycode)==53){self->cancelSelection();return nullptr;}if(type==kCGEventLeftMouseDown)return nullptr;if(type==kCGEventLeftMouseUp){auto point=CGEventGetLocation(event);AXUIElementRef system=AXUIElementCreateSystemWide(),element=nullptr;if(AXUIElementCopyElementAtPosition(system,float(point.x),float(point.y),&element)==kAXErrorSuccess){AXUIElementRef window=nullptr;if(AXUIElementCopyAttributeValue(element,kAXWindowAttribute,reinterpret_cast<CFTypeRef*>(&window))!=kAXErrorSuccess)window=static_cast<AXUIElementRef>(CFRetain(element));QString reason;if(self->attachTo(reinterpret_cast<quintptr>(window),{qRound(point.x),qRound(point.y)},&reason))self->cancelSelection();else emit self->status(reason);CFRelease(window);CFRelease(element);}CFRelease(system);return nullptr;}return event;};native_->tap=CGEventTapCreate(kCGSessionEventTap,kCGHeadInsertEventTap,kCGEventTapOptionDefault,CGEventMaskBit(kCGEventLeftMouseDown)|CGEventMaskBit(kCGEventLeftMouseUp)|CGEventMaskBit(kCGEventKeyDown),callback,this);if(!native_->tap){cancelSelection();emit status("macOS did not allow the selection event tap.");return;}native_->source=CFMachPortCreateRunLoopSource(kCFAllocatorDefault,native_->tap,0);CFRunLoopAddSource(CFRunLoopGetMain(),native_->source,kCFRunLoopCommonModes);native_->timeout.start(30000);emit status("Click a window to attach · Esc to cancel (experimental macOS)");emit changed();}
void MacPlatform::cancelSelection(){native_->timeout.stop();if(native_->source){CFRunLoopRemoveSource(CFRunLoopGetMain(),native_->source,kCFRunLoopCommonModes);CFRelease(native_->source);native_->source=nullptr;}if(native_->tap){CFMachPortInvalidate(native_->tap);CFRelease(native_->tap);native_->tap=nullptr;}selecting_=false;if(attached_)reconcile();else if(userVisible_)[native_->window orderFrontRegardless];emit changed();}
QString MacPlatform::registerShortcuts(QString lock,QString recover,bool validation){for(auto& key:native_->keys){if(key)UnregisterEventHotKey(key);key=nullptr;}if(validation)return {};if(!native_->handler){EventTypeSpec spec{kEventClassKeyboard,kEventHotKeyPressed};InstallApplicationEventHandler([](EventHandlerCallRef,EventRef event,void* user)->OSStatus{EventHotKeyID id{};GetEventParameter(event,kEventParamDirectObject,typeEventHotKeyID,nullptr,sizeof id,nullptr,&id);auto self=static_cast<MacPlatform*>(user);emit self->requestCommand(id.id==2?"recover":"lock");return noErr;},1,&spec,this,&native_->handler);}QStringList errors;int index=0;for(auto text:{lock,recover}){auto shortcut=parseShortcut(text);UInt32 code=0;bool found=false;TISInputSourceRef source=TISCopyCurrentKeyboardLayoutInputSource();auto data=static_cast<CFDataRef>(TISGetInputSourceProperty(source,kTISPropertyUnicodeKeyLayoutData));if(data&&shortcut){auto layout=reinterpret_cast<const UCKeyboardLayout*>(CFDataGetBytePtr(data));for(UInt32 i=0;i<128;i++){UniChar chars[4];UniCharCount length=0;UInt32 dead=0;if(UCKeyTranslate(layout,i,kUCKeyActionDown,0,LMGetKbdType(),kUCKeyTranslateNoDeadKeysBit,&dead,4,&length,chars)==noErr&&length==1&&QChar(chars[0]).toUpper().unicode()==shortcut->key){code=i;found=true;break;}}}if(source)CFRelease(source);if(!found){errors<<text+" cannot be mapped on this keyboard";++index;continue;}UInt32 mods=0;if(shortcut->modifiers&2)mods|=controlKey;if(shortcut->modifiers&1)mods|=optionKey;if(shortcut->modifiers&4)mods|=shiftKey;if(shortcut->modifiers&8)mods|=cmdKey;EventHotKeyID id{'GStQ',UInt32(index+1)};if(RegisterEventHotKey(code,mods,id,GetApplicationEventTarget(),0,&native_->keys[index])!=noErr)errors<<text+" is already in use";++index;}return errors.join("; ");}
bool MacPlatform::startupEnabled()const{return QFileInfo::exists(QDir::homePath()+"/Library/LaunchAgents/io.github.eduardojsborges.GlassStatsQt.plist");}
QString MacPlatform::setStartup(bool enabled,bool){QString path=QDir::homePath()+"/Library/LaunchAgents/io.github.eduardojsborges.GlassStatsQt.plist";if(!enabled){QFile::remove(path);return {};}QString executable=QCoreApplication::applicationFilePath().toHtmlEscaped();QDir().mkpath(QFileInfo(path).absolutePath());QSaveFile f(path);if(!f.open(QIODevice::WriteOnly))return f.errorString();f.write(("<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\"><plist version=\"1.0\"><dict><key>Label</key><string>io.github.eduardojsborges.GlassStatsQt</string><key>ProgramArguments</key><array><string>"+executable+"</string><string>--startup</string></array><key>RunAtLoad</key><true/></dict></plist>").toUtf8());return f.commit()?QString():f.errorString();}
